-- Ore, mineral and ice price history — 90 trailing days for the client's
-- market graph (MarketProxy.GetOldPriceHistory reads market_history_old).
--
-- Frozen data. It was derived once, offline, from a real market's daily
-- mineral series and this database's own invorereprocessing yields, then
-- written here as plain rows. Nothing in this repository or the running server
-- connects to that source or to any external database — this file and the
-- invTypes.basePrice values in sql/invtypes.sql are the entire result, and
-- they stand on their own.
--
-- Only the reference region's series is stored. Every other region is the same
-- curve times two scalars computed below from this database's own map tables:
--
--   price  x  a security factor — nullsec ore is worth ~15-25% more than
--             highsec ore, which is what makes hauling a decision;
--   volume x  the region's share of all stations, so a backwater does not
--             report Jita's turnover.
--
-- Dates are relative to load time, so re-running this always produces a fresh
-- trailing 90 days rather than an ageing window.
--
-- A post-load script, not a table dump: dates are relative to load time. Run it
-- after the base dumps (it reads staStations and mapSolarSystems). Safe to re-run.

SET @refSec    = 0.595580;  -- The Forge mean security, the series' own baseline
SET @refFactor = GREATEST(0.90, LEAST(1.25, 1.0 + 0.20 * (0.5 - @refSec)));
SET @refShare  = 354.0 / 5042.0;  -- The Forge's share of all stations
SET @day0      = UNIX_TIMESTAMP(UTC_DATE());

-- Reference region: typeID, days ago, volume, orders, low, high, avg.
CREATE TEMPORARY TABLE _ore_hist_ref (
  typeID    INT NOT NULL,
  dayAgo    INT NOT NULL,
  volume    BIGINT NOT NULL,
  orders    INT NOT NULL,
  lowPrice  DOUBLE NOT NULL,
  highPrice DOUBLE NOT NULL,
  avgPrice  DOUBLE NOT NULL,
  PRIMARY KEY (typeID, dayAgo)
);


-- Rows this file owns: exactly the types in the series above. History for every
-- other type is left untouched, so re-running replaces the window instead of
-- stacking a second one on top.
DELETE h FROM market_history_old h
  JOIN (SELECT DISTINCT typeID FROM _ore_hist_ref) r ON r.typeID = h.typeID;

-- Fan the series out to every region that has a station to dock at. A region
-- with nowhere to dock has no market for the client to open.
SELECT r.regionID,
       h.typeID,
       @day0 - h.dayAgo * 86400,
       GREATEST(1, ROUND(h.volume / @refShare * r.share)),
       LEAST(5000, GREATEST(1, ROUND(h.orders / @refShare * r.share))),
       ROUND(h.lowPrice  / @refFactor * r.factor, 2),
       ROUND(h.highPrice / @refFactor * r.factor, 2),
       ROUND(h.avgPrice  / @refFactor * r.factor, 2)
  FROM _ore_hist_ref h
  CROSS JOIN (
        SELECT st.regionID,
               GREATEST(0.90, LEAST(1.25, 1.0 + 0.20 * (0.5 - AVG(ss.security)))) AS factor,
               COUNT(DISTINCT st.stationID) / 5042.0 AS share
          FROM staStations st
          JOIN mapSolarSystems ss ON ss.regionID = st.regionID
         GROUP BY st.regionID
       ) r;

DROP TEMPORARY TABLE _ore_hist_ref;
